CREATE FUNCTION public.request_customer_quote_reference_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.customer_quote_id IS DISTINCT FROM OLD.customer_quote_id OR NEW.customer_quote_draft_id IS DISTINCT FROM OLD.customer_quote_draft_id THEN RAISE EXCEPTION 'Original customer quote references are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER customer_quote_references_immutable BEFORE UPDATE ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.request_customer_quote_reference_guard();
CREATE FUNCTION public.trip_payment_invoice_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.invoice_document_id IS NOT NULL AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'Invoice payments are server managed'; END IF; RETURN NEW; ELSIF TG_OP='DELETE' THEN IF OLD.invoice_document_id IS NOT NULL THEN RAISE EXCEPTION 'Invoice payment history is immutable'; END IF; RETURN OLD; END IF;
 IF NEW.invoice_document_id IS DISTINCT FROM OLD.invoice_document_id THEN RAISE EXCEPTION 'Payment invoice linkage is immutable';END IF;
 IF OLD.invoice_document_id IS NOT NULL AND (NEW.amount_cents IS DISTINCT FROM OLD.amount_cents OR NEW.platform_fee_cents IS DISTINCT FROM OLD.platform_fee_cents OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.ride_request_id IS DISTINCT FROM OLD.ride_request_id OR NEW.provider_user_id IS DISTINCT FROM OLD.provider_user_id OR NEW.payer_user_id IS DISTINCT FROM OLD.payer_user_id OR NEW.invoice_idempotency_key IS DISTINCT FROM OLD.invoice_idempotency_key OR NEW.stripe_connected_account_id IS DISTINCT FROM OLD.stripe_connected_account_id) THEN RAISE EXCEPTION 'Original invoice payment amounts and ownership are immutable'; END IF;
 IF OLD.invoice_document_id IS NOT NULL AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'Invoice payment state is server managed'; END IF; RETURN NEW;END $$;
CREATE TRIGGER invoice_payment_history_guard BEFORE INSERT OR UPDATE OR DELETE ON public.trip_payments FOR EACH ROW EXECUTE FUNCTION public.trip_payment_invoice_guard();